const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;color:var(--ink);font-family:system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;font-size:13px;line-height:1.3}\n.card *{box-sizing:border-box}\n.sheet{display:flex;flex-direction:column;gap:6px;width:100%;height:100%;min-height:0;min-width:0;padding:8px;background:var(--paper);border-radius:14px;overflow:hidden}\n.head,.bar{display:flex;align-items:center;gap:6px;flex:none;min-width:0}\n.ttl{flex:1;min-width:0}\n.t1{font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.t2{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.t2.warn{color:var(--ink);font-weight:600}\n.bar h2{flex:1;min-width:0;margin:0;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n\n.btn{font:inherit;font-size:13px;cursor:pointer;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);border-radius:10px;padding:0 10px;min-height:32px;display:inline-flex;align-items:center;justify-content:center;gap:4px;white-space:nowrap;flex:none}\n.btn.pri{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn.ghost{background:transparent}\n.btn.back{padding:0 8px}\n.btn.chip{min-height:28px;padding:0 10px;border-radius:14px;font-size:12px}\n.btn.sq{width:30px;min-height:30px;height:30px;padding:0;font-size:18px;line-height:1}\n.btn:disabled{opacity:.4;cursor:default}\n.btn:focus-visible,.inp:focus-visible,.info:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.msg{flex:none;font-size:12px;border-left:3px solid var(--accent);background:var(--soft);padding:3px 6px;border-radius:4px}\n.msg:empty{display:none}\n\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:grid;grid-template-columns:minmax(0,1fr);gap:6px;align-content:start}\n.row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:6px;padding:5px 5px 5px 7px;border:1px solid var(--line);border-left:4px solid var(--line);border-radius:10px;background:var(--panel-paper);min-width:0}\n.row.need{border-left-color:var(--accent);background:var(--soft)}\n.info{display:grid;gap:1px;min-width:0;background:none;border:0;padding:0;margin:0;text-align:left;font:inherit;color:inherit;cursor:pointer;border-radius:6px}\n.nm{display:flex;align-items:center;gap:5px;min-width:0;font-size:12px;font-weight:600}\n.nmt{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.tag{flex:none;font-style:normal;font-size:10px;font-weight:600;line-height:1;padding:3px 6px;border-radius:8px;background:var(--accent);color:var(--on-accent);white-space:nowrap}\n.tag.ok{background:var(--soft);color:var(--ink);border:1px solid var(--line)}\n.qt{display:flex;align-items:baseline;gap:3px;min-width:0;overflow:hidden;white-space:nowrap}\n.qt b{font-size:19px;line-height:1.15;font-weight:700}\n.qt i{font-style:normal;font-size:11px;color:var(--muted)}\n.step{display:flex;gap:4px}\n.gauge{display:none;gap:2px}\n.meter{position:relative;display:block;height:6px;border-radius:3px;background:var(--line)}\n.fill{position:absolute;left:0;top:0;bottom:0;border-radius:3px;background:var(--accent-alt,var(--accent))}\n.row.need .fill{background:var(--accent)}\n.mark{position:absolute;top:-2px;bottom:-2px;width:2px;margin-left:-1px;background:var(--ink)}\n.thr{font-size:10px;color:var(--muted)}\n\n.empty{flex:1;min-height:0;overflow-y:auto;display:flex;flex-direction:column;gap:8px;justify-content:center}\n.etx{font-size:12px;color:var(--muted)}\n.chips{display:flex;flex-wrap:wrap;gap:5px}\n\n.body{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:8px}\n.dgrid{display:grid;grid-template-columns:minmax(0,1fr);gap:8px;align-content:start}\n.left,.right{display:grid;gap:5px;align-content:start;min-width:0}\n.big{display:flex;align-items:baseline;gap:5px;flex-wrap:wrap;min-width:0}\n.big b{font-size:28px;line-height:1.05;font-weight:700}\n.big i{font-style:normal;color:var(--muted);font-size:13px}\n.big .tag{align-self:center}\n.sub{font-size:12px;color:var(--muted)}\n.sub.err{color:var(--ink);font-weight:600;border-left:3px solid var(--accent);background:var(--soft);padding:2px 6px;border-radius:4px}\n.bigmeter .meter{height:8px}\n.adj{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px;align-items:center}\n.unit{font-size:12px;color:var(--muted);min-width:1em}\n.go{display:grid;grid-template-columns:1fr 1fr;gap:6px}\n.go .btn{min-height:38px}\n.sec{grid-column:1/-1;display:flex;align-items:center;justify-content:flex-end;gap:6px;flex-wrap:wrap}\n.meta{margin-right:auto;font-size:11px;color:var(--muted)}\n.ask{margin-right:auto;font-size:12px;font-weight:600}\n\n.inp{font:inherit;font-size:14px;color:var(--ink);background:var(--panel-paper);border:1px solid var(--line);border-radius:8px;padding:5px 8px;min-height:34px;width:100%;min-width:0}\n.fgrid{display:grid;grid-template-columns:minmax(0,1fr);gap:8px;align-content:start}\n.cell{display:grid;gap:6px;align-content:start;min-width:0}\n.fld{display:grid;gap:3px;min-width:0}\n.lb{font-size:11px;color:var(--muted)}\n.two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:6px;min-width:0}\n.foot{flex:none;display:grid;grid-template-columns:1fr 2fr;gap:6px}\n.foot .btn{min-height:36px}\n\n/* 3x3 : 194x194 */\n.card[data-size=\"3x3\"] .sheet{padding:7px;gap:5px}\n.card[data-size=\"3x3\"] .big b{font-size:24px}\n.card[data-size=\"3x3\"] .bigmeter{display:none}\n.card[data-size=\"3x3\"] .btn.add{min-height:30px;padding:0 9px}\n.card[data-size=\"3x3\"] .go .btn{min-height:36px}\n\n/* 6x3 : 404x194 */\n.card[data-size=\"6x3\"] .sheet{padding:8px;gap:5px}\n.card[data-size=\"6x3\"] .list{grid-template-columns:repeat(2,minmax(0,1fr))}\n.card[data-size=\"6x3\"] .dgrid,.card[data-size=\"6x6\"] .dgrid{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px 14px}\n.card[data-size=\"6x3\"] .fgrid,.card[data-size=\"6x6\"] .fgrid{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px 14px}\n.card[data-size=\"6x3\"] .bigmeter{display:none}\n\n/* 3x6 : 194x404 */\n.card[data-size=\"3x6\"] .sheet{padding:10px;gap:8px}\n.card[data-size=\"3x6\"] .gauge,.card[data-size=\"6x6\"] .gauge{display:grid}\n.card[data-size=\"3x6\"] .row,.card[data-size=\"6x6\"] .row{padding:8px 6px 8px 9px}\n.card[data-size=\"3x6\"] .info,.card[data-size=\"6x6\"] .info{gap:3px}\n\n/* 6x6 : 404x404 */\n.card[data-size=\"6x6\"] .sheet{padding:14px;gap:10px}\n.card[data-size=\"6x6\"] .list{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}\n.card[data-size=\"6x6\"] .t1{font-size:18px}\n.card[data-size=\"6x6\"] .t2{font-size:12px}\n.card[data-size=\"6x6\"] .nm{font-size:14px}\n.card[data-size=\"6x6\"] .qt b{font-size:24px}\n.card[data-size=\"6x6\"] .big b{font-size:40px}\n";
function num(v){
  if(v===null||v===undefined)return NaN;
  if(typeof v==='string'&&v.trim()==='')return NaN;
  const n=Number(v);
  return Number.isFinite(n)?n:NaN;
}
function r2(n){return Math.round(n*100)/100}
function fmt(n){return String(r2(n))}
function norm(s){
  const src=s&&Array.isArray(s.items)?s.items:[];
  const items=src.filter(x=>x&&x.id).map(x=>{
    const q=Number(x.qty);
    const l=(x.low===null||x.low===undefined||x.low==='')?NaN:Number(x.low);
    return {
      id:x.id,
      name:String(x.name||''),
      qty:Number.isFinite(q)&&q>0?q:0,
      unit:String(x.unit||''),
      low:Number.isFinite(l)&&l>=0?l:null,
      at:String(x.at||'')
    };
  });
  return {items:items};
}
function needs(it){return it.qty<=0||(it.low!==null&&it.qty<it.low)}
function sortItems(items){
  const w=items.map((it,i)=>({it:it,i:i,n:needs(it)}));
  w.sort((a,b)=>{
    if(a.n!==b.n)return a.n?-1:1;
    if(a.n){
      const ra=a.it.low>0?a.it.qty/a.it.low:0;
      const rb=b.it.low>0?b.it.qty/b.it.low:0;
      if(ra!==rb)return ra-rb;
    }
    return a.i-b.i;
  });
  return w.map(x=>x.it);
}
function applyDelta(s,id,d,at){
  const n=norm(s);
  let from=0,to=0;
  const items=n.items.map(it=>{
    if(it.id!==id)return it;
    from=it.qty;
    to=Math.max(0,r2(it.qty+d));
    return Object.assign({},it,{qty:to,at:at});
  });
  return {state:Object.assign({},s,{items:items}),from:from,to:to};
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  const items=norm(state).items;
  const BASE={view:'list',id:'',draft:null,amt:'1',err:'',note:'',del:false,saving:false};
  if(!ui.view)Object.assign(ui,BASE);
  const PRESETS=['尿不湿','奶粉','湿巾'];
  const nextUi=p=>Object.assign({},BASE,p);
  const go=p=>{Object.assign(ui,{err:'',note:'',del:false,saving:false},p);redraw();};
  const fail=msg=>{ui.err=msg;ui.saving=false;redraw();};
  const h=(tag,attrs,...kids)=>{
    const flat=[];
    kids.forEach(k=>{
      if(Array.isArray(k)){k.forEach(x=>{if(x!==null&&x!==undefined&&x!==false)flat.push(x);});}
      else if(k!==null&&k!==undefined&&k!==false)flat.push(k);
    });
    return el(tag,attrs||{},...flat);
  };
  const btn=(label,cls,onclick,extra)=>{
    const b=h('button',Object.assign({class:'btn '+(cls||''),onclick:onclick},extra||{}),label);
    b.setAttribute('type','button');
    return b;
  };

  function meter(it){
    if(it.low===null||it.low<=0)return null;
    const max=Math.max(it.qty,it.low*2);
    const fill=h('span',{class:'fill'});
    const mark=h('span',{class:'mark'});
    fill.style.width=(it.qty/max*100)+'%';
    mark.style.left=(it.low/max*100)+'%';
    const m=h('span',{class:'meter',title:'提醒线 '+fmt(it.low)+it.unit},fill,mark);
    return m;
  }

  function quick(it,d){
    update(s=>applyDelta(s,it.id,d,day()).state).then(()=>{
      if(ui.err){ui.err='';redraw();}
    }).catch(()=>fail('保存失败，数量没有改动，请重试'));
  }

  function openForm(it,pre){
    const draft=it
      ?{id:it.id,name:it.name,qty:fmt(it.qty),unit:it.unit,low:it.low===null?'':fmt(it.low)}
      :{id:'',name:(pre&&pre.name)||'',qty:'',unit:'',low:''};
    go({view:'form',draft:draft});
  }

  function row(it){
    const need=needs(it);
    const out=it.qty<=0;
    const tag=out?'已用完':(need?'快用完':'');
    const m=meter(it);
    const gauge=m?h('span',{class:'gauge'},m,h('span',{class:'thr'},'低于 '+fmt(it.low)+it.unit+' 提醒')):null;
    const info=h('button',{
      class:'info',
      'aria-label':it.name+'，还剩 '+fmt(it.qty)+it.unit+(tag?'，'+tag:'')+'，查看详情',
      onclick:()=>go({view:'detail',id:it.id,amt:'1'})
    },
      h('span',{class:'nm'},h('span',{class:'nmt'},it.name),tag?h('em',{class:'tag'},tag):null),
      h('span',{class:'qt'},h('b',{},fmt(it.qty)),it.unit?h('i',{},it.unit):null),
      gauge
    );
    info.setAttribute('type','button');
    const minus=btn('−','sq',()=>quick(it,-1),{'aria-label':'用掉 1 '+it.unit+it.name,title:'用掉 1',disabled:out});
    const plus=btn('+','sq',()=>quick(it,1),{'aria-label':'买来 1 '+it.unit+it.name,title:'买来 1'});
    return h('div',{class:'row'+(need?' need':'')},info,h('div',{class:'step'},minus,plus));
  }

  function renderList(){
    const list=sortItems(items);
    const lowN=list.filter(needs).length;
    const sub=!items.length?'还没有记录':(lowN?lowN+' 样快用完':'都够用');
    const head=h('div',{class:'head'},
      h('div',{class:'ttl'},h('div',{class:'t1'},'宝宝用品库存'),h('div',{class:'t2'+(lowN?' warn':'')},(lowN?'! ':'')+sub)),
      btn('+ 添加','pri add',()=>openForm(null))
    );
    let body;
    if(!items.length){
      body=h('div',{class:'empty'},
        h('div',{class:'etx'},'记下每样还剩多少，用掉点 −，买来点 +。先选一个，或点「添加」自己写：'),
        h('div',{class:'chips'},PRESETS.map(n=>btn(n,'chip',()=>openForm(null,{name:n}))))
      );
    }else{
      body=h('div',{class:'list'},list.map(row));
    }
    const msg=h('div',{class:'msg',role:'alert'});
    if(ui.err)msg.textContent='! '+ui.err;
    return h('div',{class:'sheet'},head,msg,body);
  }


  function renderDetail(it){
    const need=needs(it);
    const out=it.qty<=0;
    const tag=out?'已用完':(need?'快用完':'够用');
    const u=it.unit;
    let desc;
    if(it.low===null)desc='还没设快用完的数量';
    else if(need)desc=out?'已经用完，该买了（提醒线 '+fmt(it.low)+u+'）':'低于提醒线 '+fmt(it.low)+u+'，还差 '+fmt(it.low-it.qty)+u;
    else desc='提醒线 '+fmt(it.low)+u+'，还多 '+fmt(it.qty-it.low)+u;
    const subEl=h('div',{class:'sub'});
    if(ui.err){subEl.textContent='! '+ui.err;subEl.className='sub err';}
    else subEl.textContent=ui.note||desc;

    const amt=h('input',{class:'inp amt','aria-label':'这次的数量',oninput:e=>{ui.amt=e.target.value;}});
    amt.setAttribute('type','number');
    amt.setAttribute('step','any');
    amt.setAttribute('min','0');
    amt.setAttribute('inputmode','decimal');
    amt.value=String(ui.amt);

    function adjust(sign){
      const a=num(ui.amt);
      if(!(a>0)){subEl.textContent='! 请先填一个大于 0 的数量';subEl.className='sub err';return;}
      let info={from:0,to:0};
      update(s=>{const r=applyDelta(s,it.id,sign*a,day());info=r;return r.state;}).then(()=>{
        ui.err='';
        if(sign<0){
          ui.note=a>info.from+0.000001
            ?'只剩 '+fmt(info.from)+u+'，已减到 0'
            :'用掉 '+fmt(a)+u+'，还剩 '+fmt(info.to)+u;
        }else{
          ui.note='买来 '+fmt(a)+u+'，现在有 '+fmt(info.to)+u;
        }
        redraw();
      }).catch(()=>{ui.note='';ui.err='保存失败，数量没有改动，请重试';redraw();});
    }
    amt.onkeydown=e=>{if(e.key==='Enter')adjust(-1);};

    const m=meter(it);
    const left=h('div',{class:'left'},
      h('div',{class:'big'},h('b',{},fmt(it.qty)),u?h('i',{},u):null,h('em',{class:'tag'+(need?'':' ok')},tag)),
      subEl,
      m?h('div',{class:'bigmeter'},m):null
    );
    const right=h('div',{class:'right'},
      h('div',{class:'adj'},amt,h('span',{class:'unit'},u||'')),
      h('div',{class:'go'},
        btn('− 用掉','',()=>adjust(-1)),
        btn('+ 买来','pri',()=>adjust(1))
      )
    );
    let sec;
    if(ui.del){
      sec=h('div',{class:'sec'},
        h('span',{class:'ask'},'删除「'+it.name+'」？'),
        btn('确定删除','pri',()=>{
          commit(s=>{
            const n=norm(s);
            return Object.assign({},s,{items:n.items.filter(x=>x.id!==it.id)});
          },nextUi({view:'list'})).catch(()=>fail('删除失败，请重试'));
        }),
        btn('取消','',()=>go({view:'detail'}))
      );
    }else{
      sec=h('div',{class:'sec'},
        it.at?h('span',{class:'meta'},'最近变动 '+it.at):null,
        btn('删除','ghost',()=>go({del:true,view:'detail'}))
      );
    }
    return h('div',{class:'sheet'},
      h('div',{class:'bar'},
        btn('‹ 返回','back',()=>go({view:'list',id:''}),{'aria-label':'返回列表'}),
        h('h2',{},it.name),
        btn('编辑','',()=>openForm(it))
      ),
      h('div',{class:'body'},h('div',{class:'dgrid'},left,right,sec))
    );
  }

  function saveForm(errBox){
    const d=ui.draft;
    if(!d||ui.saving)return;
    const name=String(d.name).trim();
    const q=num(d.qty);
    const l=num(d.low);
    let err='';
    if(!name)err='请填写名称';
    else if(!(q>=0))err='请填写现有数量（0 或更大的数字）';
    else if(!(l>=0))err='请填写「快用完数量」（0 或更大的数字）';
    if(err){ui.err=err;errBox.textContent='! '+err;return;}
    const isNew=!d.id;
    const id=d.id||uid();
    const rec={id:id,name:name,qty:r2(q),unit:String(d.unit).trim(),low:r2(l),at:day()};
    ui.saving=true;
    ui.err='';
    commit(s=>{
      const n=norm(s);
      const exists=n.items.some(x=>x.id===id);
      const list=exists?n.items.map(x=>x.id===id?Object.assign({},x,rec):x):n.items.concat([rec]);
      return Object.assign({},s,{items:list});
    },nextUi(isNew?{view:'list'}:{view:'detail',id:id})).catch(()=>{
      ui.saving=false;
      ui.err='保存失败，数据没有改动，请重试';
      errBox.textContent='! '+ui.err;
    });
  }

  function renderForm(){
    const d=ui.draft||{id:'',name:'',qty:'',unit:'',low:''};
    ui.draft=d;
    const errBox=h('div',{class:'msg',role:'alert'});
    if(ui.err)errBox.textContent='! '+ui.err;
    function inp(type,key,ph){
      const n=h('input',{class:'inp',oninput:e=>{d[key]=e.target.value;},onkeydown:e=>{if(e.key==='Enter')saveForm(errBox);}});
      n.setAttribute('type',type);
      if(ph)n.setAttribute('placeholder',ph);
      if(type==='number'){n.setAttribute('step','any');n.setAttribute('min','0');n.setAttribute('inputmode','decimal');}
      n.value=String(d[key]);
      return n;
    }
    const field=(label,node,more)=>h('label',{class:'fld'},h('span',{class:'lb'},label),node,more);
    const nameIn=inp('text','name','例如 尿不湿');
    const unitIn=inp('text','unit','片 / 罐 / 包');
    unitIn.setAttribute('list','unit-list');
    const used=items.map(x=>x.name);
    const presets=(!d.id&&!String(d.name).trim())?PRESETS.filter(n=>used.indexOf(n)<0):[];
    const chips=presets.length?h('div',{class:'chips'},presets.map(n=>btn(n,'chip',()=>{d.name=n;redraw();}))):null;
    const dl=h('datalist',{id:'unit-list'},['片','包','罐','盒','袋','瓶','条','个'].map(x=>h('option',{value:x})));
    const body=h('div',{class:'body'},
      h('div',{class:'fgrid'},
        h('div',{class:'cell'},field('名称*',nameIn),chips),
        h('div',{class:'two'},field('现有数量*',inp('number','qty','0')),field('单位',unitIn)),
        field('快用完数量*（低于它就排到最前）',inp('number','low','例如 10'))
      ),
      dl
    );
    const foot=h('div',{class:'foot'},
      btn('取消','',()=>go({view:d.id?'detail':'list',draft:null})),
      btn(d.id?'保存修改':'保存','pri',()=>saveForm(errBox),{disabled:!!ui.saving})
    );
    return h('div',{class:'sheet'},
      h('div',{class:'bar'},h('h2',{},d.id?'编辑用品':'添加用品')),
      body,errBox,foot
    );
  }

  function render(){
    if(ui.view==='form')return renderForm();
